import functools
import inspect
from typing import ForwardRef, get_type_hints, Any, Callable, Dict
from fastapi.dependencies.utils import get_typed_signature

class A:
    pass

def wrapped_func(x: "A"):
    return x

@functools.wraps(wrapped_func)
def wrapper(x):
    return wrapped_func(x)

# Now wrapper.__globals__ is the same as wrapped_func.__globals__ because they are in the same module.
# To make them different, we need to define them in different modules.

# Instead of creating a module, let's just use a function that defines another function.
def create_wrapper():
    class B:
        pass
    def inner_func(x: "B"):
        return x

    @functools.wraps(inner_func)
    def wrapper(x):
        return inner_func(x)

    return wrapper, B

wrapper, B_class = create_wrapper()

# wrapper.__globals__ is the globals of create_wrapper's module.
# inner_func.__globals__ is also the globals of create_wrapper's module.
# This is still not quite right.

# Let's try this:
import types
mod = types.ModuleType("mod")
mod.B = B_class
def inner_func(x: "B"):
    return x
inner_func.__module__ = "mod"
inner_func.__globals__ = mod.__dict__

def wrapper(x):
    return inner_func(x)
functools.wraps(inner_func, wrapper)

# Now wrapper.__globals__ is the current module's globals.
# inner_func.__globals__ is mod.__dict__.
# wrapper.__annotations__ is {'x': 'B'} (copied from inner_func)

try:
    # This should work because get_type_hints uses __wrapped__
    print("get_type_hints(wrapper):", get_type_hints(wrapper))
except Exception as e:
    print("get_type_hints(wrapper) failed:", e)

try:
    sig = get_typed_signature(wrapper)
    print("get_typed_signature(wrapper):", sig)
except Exception as e:
    print("get_typed_signature(wrapper) failed:", e)
    import traceback
    traceback.print_exc()
